## Code Example

```typescript
type ValidationResult = { ok: boolean; error?: string };

interface Validator {
  name: string;
  validate(value: any): Promise<ValidationResult>;
}

class ValidatorRegistry {
  private registry = new Map<string, (opts?: any) => Validator>();
  register(name: string, factory: (opts?: any) => Validator) {
    this.registry.set(name, factory);
  }
  get(name: string, opts?: any): Validator | null {
    const f = this.registry.get(name);
    return f ? f(opts) : null;
  }
}
```

